function subtractDaysFromToday(days) {
    if (typeof days !== 'number') {
        throw new Error('The days parameter must be a number');
    }

    var today = new Date();
    var resultDate = new Date(today);

    // Subtracting the specified number of days
    resultDate.setDate(today.getDate() - days);
    
    return resultDate;
}

function toSalesforceDateFormat(date) {
    if (!(date instanceof Date)) {
        throw new Error('The input must be a Date object');
    }

    var year = date.getFullYear();
    var month = date.getMonth() + 1; // Months are zero-based, so add 1
    var day = date.getDate();

    // Ensure two-digit month and day
    var monthString = month < 10 ? '0' + month : month;
    var dayString = day < 10 ? '0' + day : day;

    return year + '-' + monthString + '-' + dayString + 'T00:00:00.000-04:00';
}

