function matchOrderNumberAndTransform() {
    // Safely extract the order detail records from the 'actions' source (as an array)
    var actionsOrderDetails = actions.findordersbycriteria.OrderList || [];
    
    // Extract the single order detail record from the 'views' source (as an object)
    var viewsOrderDetail = views.findordersbycriteria || {};

    // Log the raw data for debugging purposes
    ZT.log('actions data: ' + JSON.stringify(actionsOrderDetails));
    ZT.log('views data: ' + JSON.stringify(viewsOrderDetail));

    // Extract the PCS_Order_Key__c value from the 'views' order detail
    var viewOrderKey = viewsOrderDetail.orderKey;

    // Loop through each order detail from the 'actions' source
    for (var i = 0; i < actionsOrderDetails.length; i++) {
        // Get the PCS_Order_Key__c for the current record from 'actions'
        var actionOrderKey = actionsOrderDetails[i].orderKey;
        ZT.log('Actions Order Number: ' + actionOrderKey);

        // Log the comparison for debugging
        ZT.log("Comparing with Views Order Number: " + viewOrderKey);

        // If the order keys match, store the matching record in the transform context
        if (actionOrderKey === viewOrderKey) {
            ZT.setTransformData('matchedOrder', actionsOrderDetails[i]);
            ZT.log('Matched and set transform data: ' + JSON.stringify(actionsOrderDetails[i]));
            return; // Exit after finding the first match
        }
    }

    // If no match was found, log that as well
    ZT.log('No matching order found between actions and views.');
}

